// ═══════════════════════════════════════════════════════
//  DARKWEB MONITOR — Network Config
// ═══════════════════════════════════════════════════════
//
//  LOCAL  (same WiFi): Flask at 192.168.0.4:5001
//  REMOTE (Tailscale): Flask at 100.106.176.128:5001
//
//  n8n URLs:
//  LOCAL  → http://192.168.0.10:5678/webhook/darkweb-scan
//  REMOTE → http://100.91.244.44:5678/webhook/darkweb-scan
// ═══════════════════════════════════════════════════════

const API_SECRET = 'darkweb_secret_2024';

// ── Both API endpoints ───────────────────────────────
// n8n will try local first, fallback to Tailscale
const API_LOCAL    = 'http://192.168.0.4:5001';       // Mac local IP
const API_TAILSCALE = 'https://demmisto-internship.onrender.com';  // Mac Tailscale IP

// ── Extract input ─────────────────────────────────────
const body = $input.first().json.body || $input.first().json;
let target = (body.target || body.url || body.domain || body.ip || '').trim();
const type = (body.type || '').trim().toLowerCase();

if (!target) throw new Error('❌ Missing field: target (domain / ip / url)');

// ── Auto detect type ──────────────────────────────────
let scanType = type;
if (!scanType) {
  scanType = /^\d{1,3}(\.\d{1,3}){3}$/.test(target) ? 'ip' : 'domain';
}

// ── Clean URL → bare domain ───────────────────────────
if (scanType === 'domain') {
  target = target
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./i, '')
    .split('/')[0].split('?')[0].trim();
}

return [{
  json: {
    target,
    original:      body.target || target,
    type:          scanType,
    triggered_at:  new Date().toISOString(),
    api_local:     API_LOCAL,
    api_tailscale: API_TAILSCALE,
    api_secret:    API_SECRET
  }
}];

// ── Pick working API endpoint ─────────────────────────
const validate = $('✅ Validate Input').item.json;
const healthResult = $input.first().json;

// Check if local API responded with status 200
const localOk = healthResult?.statusCode === 200 || healthResult?.status === 'online';

const api_base = localOk ? validate.api_local : validate.api_tailscale;

console.log(`[NETWORK] Local OK: ${localOk} → Using: ${api_base}`);

return [{
  json: {
    target:      validate.target,
    type:        validate.type,
    api_base,
    api_secret:  validate.api_secret,
    network:     localOk ? 'local' : 'tailscale',
    triggered_at: validate.triggered_at
  }
}];

const scan    = $input.first().json;
const network = $('🌐 Pick Network').item.json.network || 'unknown';

const threatLevel = scan.threat_level || 'UNKNOWN';
const aiAnalysis  = scan.ai_analysis  || 'No analysis available';
const alerts      = scan.alerts_sent  || {};

const emoji = {
  CRITICAL: '🔴', HIGH: '🟠',
  MEDIUM:   '🟡', LOW:  '🟢', CLEAN: '✅'
}[threatLevel] || '⚪';

const summary = aiAnalysis
  .split('\n')
  .map(l => l.replace(/\*\*/g, '').trim())
  .find(l => l.length > 20 && !l.toUpperCase().includes('THREAT SUMMARY'))
  || aiAnalysis.slice(0, 250);

// Alert statuses
const tgSent         = alerts.telegram?.status === 'sent';
const tgScreenshot   = alerts.telegram_screenshot?.status === 'sent';
const tgPdf          = alerts.telegram_pdf?.status === 'sent';

return [{
  json: {
    status:             'complete',
    scan_id:            scan.scan_id      || 'N/A',
    target:             scan.target       || 'N/A',
    target_type:        scan.target_type  || 'N/A',
    threat_level:       threatLevel,
    threat_emoji:       emoji,
    summary,
    tg_sent:            tgSent,
    tg_screenshot_sent: tgScreenshot,
    tg_pdf_sent:        tgPdf,
    pdf_url:            scan.pdf_url      || null,
    tokens_used:        scan.tokens_used  || 0,
    network_used:       network,
    completed_at:       scan.completed_at || new Date().toISOString()
  }
}];
